package com.commercecore.shipping;import com.commercecore.order.CustomerOrder;import jakarta.persistence.*;import java.time.Instant;import java.util.*;import java.util.regex.Pattern;@Entity@Table(name="shipments")public class Shipment{private static final Pattern TRACK=Pattern.compile("[A-Za-z0-9][A-Za-z0-9._/-]{2,99}");@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="order_id",nullable=false,unique=true)private CustomerOrder order;@Enumerated(EnumType.STRING)@Column(name="service_level",nullable=false,length=16)private ShippingServiceLevel serviceLevel;@Column(nullable=false,length=100)private String carrier;@Column(name="tracking_number",nullable=false,length=100)private String trackingNumber;@Column(name="estimated_delivery_at")private Instant estimatedDeliveryAt;@Column(name="shipped_at")private Instant shippedAt;@Column(name="delivered_at")private Instant deliveredAt;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version@Column(nullable=false)private long version;protected Shipment(){}public Shipment(CustomerOrder o,String carrier,String tracking,Instant estimated){order=o;serviceLevel=o.getShippingServiceLevel();this.carrier=text(carrier,100);trackingNumber=text(tracking,100);if(!TRACK.matcher(trackingNumber).matches())throw new IllegalArgumentException();estimatedDeliveryAt=estimated;}public void shipped(Instant at){if(shippedAt!=null)throw new IllegalStateException();shippedAt=at;}public void delivered(Instant at){if(shippedAt==null||deliveredAt!=null)throw new IllegalStateException();deliveredAt=at;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void touch(){updatedAt=Instant.now();}private static String text(String s,int max){if(s==null||s.isBlank()||s.trim().length()>max)throw new IllegalArgumentException();return s.trim();}public UUID getId(){return id;}public CustomerOrder getOrder(){return order;}public ShippingServiceLevel getServiceLevel(){return serviceLevel;}public String getCarrier(){return carrier;}public String getTrackingNumber(){return trackingNumber;}public Instant getEstimatedDeliveryAt(){return estimatedDeliveryAt;}public Instant getShippedAt(){return shippedAt;}public Instant getDeliveredAt(){return deliveredAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
